import React, { useState, useMemo } from "react";
import "../styles/S";
import { onSkinAnalyze } from "../api/onSkinAnalyze";
import { onProductRecommend } from "../api/onProductRecommend";

export default function SkinAnalyzer() {
  const [photo, setPhoto] = useState(null);
  const [photoPreview, setPhotoPreview] = useState(null);
  const [analysis, setAnalysis] = useState(null);
  const [recommendations, setRecommendations] = useState("");
  const [loading, setLoading] = useState(false);
  const [loadingRec, setLoadingRec] = useState(false);

  // 📌 Загрузка фото
  const handlePhotoChange = (e) => {
    const file = e.target.files[0];
    if (!file) return;

    setPhoto(file);

    const reader = new FileReader();
    reader.onloadend = () => setPhotoPreview(reader.result);
    reader.readAsDataURL(file);
  };

  // 📌 useMemo — кэшируем результат анализа
  const memoizedAnalysis = useMemo(() => {
    return analysis;
  }, [analysis]);

  // 📌 Анализ кожи (через XMLHttpRequest + Promise)
  const handleAnalyze = () => {
    if (!photo) {
      alert("Загрузите фото");
      return;
    }

    setLoading(true);
    setAnalysis(null);
    setRecommendations("");

    onSkinAnalyze(photo)
      .then((data) => setAnalysis(data))
      .catch(() => alert("Ошибка анализа кожи"))
      .finally(() => setLoading(false));
  };

  // 📌 Рекомендации (AI-консультант)
  const handleRecommendations = () => {
    if (!memoizedAnalysis) {
      alert("Сначала выполните анализ");
      return;
    }

    setLoadingRec(true);

    onProductRecommend(memoizedAnalysis)
      .then((data) => setRecommendations(data))
      .catch(() => alert("Ошибка рекомендаций"))
      .finally(() => setLoadingRec(false));
  };

  return (
    <div className="skin-analyzer">
      <div className="container">
        <h2 className="title">🧬 Анализ кожи</h2>

        {/* Загрузка фото */}
        <input type="file" accept="image/*" onChange={handlePhotoChange} />

        {photoPreview && (
          <div className="photo-preview">
            <img src={photoPreview} alt="Предпросмотр" />
          </div>
        )}

        <button onClick={handleAnalyze} disabled={loading}>
          {loading ? "Анализ..." : "Анализировать кожу"}
        </button>

        {/* Результаты анализа */}
        {memoizedAnalysis && (
          <pre className="analysis-result">
            {JSON.stringify(memoizedAnalysis, null, 2)}
          </pre>
        )}

        <button onClick={handleRecommendations} disabled={loadingRec}>
          {loadingRec ? "Подготовка рекомендаций..." : "Получить рекомендации"}
        </button>

        {/* Рекомендации */}
        {recommendations && (
          <div className="recommendations">
            <h3>Рекомендации по уходу</h3>
            <p>{recommendations}</p>
          </div>
        )}
      </div>
    </div>
  );
}
